<?php
require dirname(__DIR__).'/configuracion/config.php';
require dirname(__DIR__).'/configuracion/autentifica_almacen.php';
require_once __DIR__.'/proveedores_lib.php';
$fields=array('RAZON_SOCIAL'=>255,'nombre_comercial'=>150,'NIF'=>100,'DOMICILIO'=>255,'LOCALIDAD'=>255,'CP'=>10,'TELEFONO1'=>100,'TELEFONO2'=>100,'MOVIL'=>100,'FAX'=>100,'EMAIL'=>255,'REGISTRO_SANITARIO'=>255,'OBSERVACIONES'=>10000,'CUENTA_BANCO'=>50,'CUENTA_CARGO'=>50,'NOMBRE_CONT'=>255,'TELEFONO_CONT'=>100,'EMAIL_CONT'=>255,'PUESTO_CONT'=>255);
$values=array_fill_keys(array_keys($fields),'');$values+=array('tipo_proveedor'=>0,'estado'=>0,'FORMA_DE_PAGO'=>1,'subtipo_proveedor'=>'');$error='';
$id=app_request_int($_GET,'u',app_request_int($_POST,'u',0));$paymentMethods=array();$evaluations=array();$questionCount=0;
try{
 if($id){$rows=lap_wf_rows('SELECT * FROM proveedores WHERE ID_PROVEEDOR=?','i',array($id));if(!$rows)throw new InvalidArgumentException('El proveedor no existe.');$values=array_merge($values,$rows[0]);}
 $paymentMethods=lap_wf_rows('SELECT id_forma_pago,nombre FROM formas_de_pago_proveedores ORDER BY id_forma_pago');
 if($id){$evaluations=lap_wf_rows('SELECT e.*,CONCAT_WS(" ",u.Nombre,u.Apellido1,u.Apellido2) AS evaluador FROM proveedores_evaluaciones e LEFT JOIN usuarios u ON u.id_usuario=e.valorada_por WHERE e.id_proveedor=? ORDER BY e.fecha_valoracion DESC','i',array($id));$questionRows=lap_wf_rows('SELECT COUNT(*) AS n FROM proveedores_cuestiones');$questionCount=(int)$questionRows[0]['n'];}
 if(app_request_value($_SERVER,'REQUEST_METHOD')==='POST'){
  lap_wf_post();
  foreach($fields as $field=>$length){$raw=app_request_value($_POST,$field,$values[$field]);if(!is_scalar($raw))throw new InvalidArgumentException('Revisa los datos del proveedor.');$values[$field]=trim((string)$raw);if(mb_strlen($values[$field],'UTF-8')>$length)throw new InvalidArgumentException('El campo '.$field.' es demasiado largo.');}
  if($values['RAZON_SOCIAL']==='')throw new InvalidArgumentException('Introduce la razón social del proveedor.');
  foreach(array('EMAIL','EMAIL_CONT') as $field)if($values[$field]!==''&&!filter_var($values[$field],FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('Revisa el correo electrónico.');
  $values['estado']=app_request_int($_POST,'estado',0)===1?1:0;$values['tipo_proveedor']=app_request_int($_POST,'tipo_proveedor',0)===1?1:0;
  $values['FORMA_DE_PAGO']=max(0,app_request_int($_POST,'FORMA_DE_PAGO',(int)$values['FORMA_DE_PAGO']));
  $paymentIds=array();foreach($paymentMethods as $method)$paymentIds[]=(int)$method['id_forma_pago'];if($values['FORMA_DE_PAGO']!==0&&!in_array($values['FORMA_DE_PAGO'],$paymentIds,true))throw new InvalidArgumentException('Selecciona una forma de pago válida.');
  $categories=app_request_value($_POST,'subtipo_proveedor',array());if(!is_array($categories))$categories=array();
  $categories=array_filter($categories,'is_string');$categories=array_values(array_intersect($subtipos_proveedor,$categories));$values['subtipo_proveedor']=implode(',',$categories);
  if($values['NIF']!==''){$duplicates=lap_wf_rows('SELECT ID_PROVEEDOR FROM proveedores WHERE REPLACE(UPPER(NIF)," ","")=? AND ID_PROVEEDOR<>? LIMIT 1','si',array(str_replace(' ','',strtoupper($values['NIF'])),$id));if($duplicates)throw new InvalidArgumentException('Ya existe un proveedor con ese NIF. Busca su ficha, también entre los inactivos.');}
  $columns=array_merge(array_keys($fields),array('tipo_proveedor','estado','FORMA_DE_PAGO','subtipo_proveedor'));$params=array();foreach($columns as $field)$params[]=$values[$field];
  if($id){$sets=array();foreach($columns as $field)$sets[]='`'.$field.'`=?';$params[]=$id;lap_wf_exec('UPDATE proveedores SET '.implode(',',$sets).' WHERE ID_PROVEEDOR=?',str_repeat('s',count($params)-1).'i',$params);}
  else{$params[]=date('Y-m-d');lap_wf_exec('INSERT INTO proveedores (`'.implode('`,`',$columns).'`,fechaalta) VALUES ('.implode(',',array_fill(0,count($params),'?')).')',str_repeat('s',count($params)),$params);}
  $_SESSION['proveedor_aviso']=$id?'Proveedor actualizado.':'Proveedor creado.';header('Location: listado_proveedores.php?e='.$values['estado'],true,303);exit;
 }
}catch(Exception $e){http_response_code(422);$error=$e->getMessage();}
lap_wf_start($id?'Editar proveedor':'Nuevo proveedor','Completa los datos principales. La información adicional puede añadirse ahora o más adelante.','almacen');lap_wf_error($error);
?>
<form method="post" action="nuevo_proveedor_b.php<?=$id?'?u='.$id:''?>"><?php lap_wf_token(); ?><input type="hidden" name="u" value="<?=$id?>">
<section class="wf-card"><h2>Datos del proveedor</h2><div class="wf-grid">
<?php foreach(array('RAZON_SOCIAL'=>'Razón social','nombre_comercial'=>'Nombre comercial','NIF'=>'NIF / CIF','REGISTRO_SANITARIO'=>'Registro sanitario') as $field=>$label)lap_wf_input($label,$field,$values[$field],'text',$field==='RAZON_SOCIAL',$fields[$field]); ?>
<label>Tipo de proveedor<select name="tipo_proveedor"><option value="0">Comercial</option><option value="1" <?=$values['tipo_proveedor']==1?'selected':''?>>Interno</option></select></label><label>Estado<select name="estado"><option value="0">Activo</option><option value="1" <?=$values['estado']==1?'selected':''?>>Inactivo</option></select></label>
</div><details><summary>Tipos de suministro</summary><div class="wf-permissions"><?php $selected=explode(',',$values['subtipo_proveedor']);foreach($subtipos_proveedor as $category){ ?><label class="wf-check"><input type="checkbox" name="subtipo_proveedor[]" value="<?=app_escape($category)?>" <?=in_array($category,$selected,true)?'checked':''?>><?=app_escape($category)?></label><?php } ?></div></details></section>
<section class="wf-card"><h2>Contacto y dirección</h2><div class="wf-grid"><?php foreach(array('EMAIL'=>'Correo electrónico','TELEFONO1'=>'Teléfono','MOVIL'=>'Móvil','DOMICILIO'=>'Dirección','LOCALIDAD'=>'Localidad','CP'=>'Código postal') as $field=>$label)lap_wf_input($label,$field,$values[$field],$field==='EMAIL'?'email':'text',false,$fields[$field]); ?></div></section>
<details class="wf-card"><summary>Otros contactos y datos de pago</summary><div class="wf-grid"><?php foreach(array('TELEFONO2'=>'Segundo teléfono','FAX'=>'Fax','NOMBRE_CONT'=>'Persona de contacto','PUESTO_CONT'=>'Puesto de la persona de contacto','TELEFONO_CONT'=>'Teléfono de contacto','EMAIL_CONT'=>'Correo de contacto','CUENTA_BANCO'=>'Cuenta bancaria / IBAN','CUENTA_CARGO'=>'Cuenta de cargo') as $field=>$label)lap_wf_input($label,$field,$values[$field],$field==='EMAIL_CONT'?'email':'text',false,$fields[$field]); ?><label>Forma de pago<select name="FORMA_DE_PAGO"><option value="0">Sin especificar</option><?php foreach($paymentMethods as $method){ ?><option value="<?=(int)$method['id_forma_pago']?>" <?=(int)$values['FORMA_DE_PAGO']===(int)$method['id_forma_pago']?'selected':''?>><?=app_escape($method['nombre'])?></option><?php } ?></select></label></div><p class="wf-help">Los datos de pago existentes se conservan al editar la ficha.</p></details>
<section class="wf-card"><label>Observaciones<textarea name="OBSERVACIONES" maxlength="10000"><?=app_escape($values['OBSERVACIONES'])?></textarea></label></section>
<div class="wf-actions"><button class="wf-btn" type="submit">Guardar proveedor</button><a class="wf-btn secondary" href="listado_proveedores.php">Cancelar</a></div></form>
<?php if($id){ ?><section class="wf-card"><h2>Evaluaciones del proveedor</h2><a class="wf-btn secondary" href="nueva_evaluacion.php?u=<?=$id?>">Nueva evaluación</a><div class="wf-list"><?php foreach($evaluations as $evaluation){$average=0;for($n=1;$n<=$questionCount;$n++)$average+=isset($evaluation['cuestion'.$n])?(float)$evaluation['cuestion'.$n]:0;$average=$questionCount?$average/$questionCount:0; ?><article class="wf-supplier"><div><h3><?=app_escape(date('d/m/Y',strtotime($evaluation['fecha_valoracion'])))?></h3><p><?=app_escape($evaluation['evaluador']?:'Desconocido')?> · Promedio: <?=number_format($average,2,',','.')?></p></div><div class="wf-actions"><a class="wf-btn secondary" href="nueva_evaluacion.php?u=<?=$id?>&amp;e=<?=(int)$evaluation['id_evaluacion']?>">Editar evaluación</a><a class="wf-btn secondary" href="ver_evaluacion.php?u=<?=$id?>&amp;e=<?=(int)$evaluation['id_evaluacion']?>">Ver / Imprimir</a><a class="wf-btn danger" href="eliminar_evaluacion.php?u=<?=$id?>&amp;e=<?=(int)$evaluation['id_evaluacion']?>&amp;_csrf=<?=rawurlencode(app_csrf_token())?>" onclick="return confirm('¿Eliminar esta evaluación? Esta acción no se puede deshacer.');">Eliminar evaluación</a></div></article><?php } if(!$evaluations){ ?><p class="wf-help">Todavía no hay evaluaciones.</p><?php } ?></div></section><?php } lap_wf_end(); ?>
